// Missile interception. A ballistic missile is launched from 450 m (+-80 m) out at a random bearing (+-50 deg) and
// aimed at the defended point (the drone's launch pad); it lands there ~11 s later. The experiment's "threat" block
// makes the platform fly the missile and points the drone's target sensor at it, so target.dx/dy/dz is the seeker's
// line of sight to the missile. The interceptor (Racer quad) must hit it (within 2.5 m) as early and as far from the
// pad as possible, without wasting energy.
// Controller: predictive guidance (lead the target by its estimated velocity times time-to-go, plus gravity drop)
// feeding the same cascaded quad flight controller as drone-race.json. 12 genes, all evolved.
// Reward terms:
//   intercept - one-off +10 for a hit (missile within KILL m of the drone)
//   standoff  - one-off, up to +30: how far from the pad the hit happened (per 10 m); hits within SAFE m don't count
//   early     - one-off, up to +5: how much of the episode was left at the hit
//   closing   - always-on shaping before a hit: penalty for distance to the missile
//   miss      - at the end without a hit: penalty for the closest approach (m / 5)
//   leak      - one-off -10 when the missile reaches the pad
//   energy    - penalty for mean motor command (battery)
//   crash     - one-off penalty for crashing / flipping before the hit (worst-case closing for the time left + leak)
const KILL = 2.5;   // same as threat.killRadius in the experiment
const SAFE = 30;    // a "hit" closer than this to the pad does not count: the warhead still lands on the defended point
function terms() { return ["intercept", "standoff", "early", "closing", "miss", "leak", "energy", "crash"]; }

function seeker(ctx) {
  const i = ctx.in, s = ctx.state, m = ctx.memory, dt = ctx.dt;
  const r = { x: i["target.dx"], y: i["target.dy"], z: i["target.dz"] };
  if (m.pad === undefined) { m.pad = { x: s.x, y: s.y, z: s.z }; m.minD = 1e9; }
  // missile velocity = d/dt(line of sight) + own velocity (lightly filtered)
  if (m.pr !== undefined && ctx.t > m.pt) {
    const h = ctx.t - m.pt;
    const vm = { x: (r.x - m.pr.x) / h + s.vx, y: (r.y - m.pr.y) / h + s.vy, z: (r.z - m.pr.z) / h + s.vz };
    if (m.vm === undefined) m.vm = vm;
    else { m.vm.x += (vm.x - m.vm.x) * 0.5; m.vm.y += (vm.y - m.vm.y) * 0.5; m.vm.z += (vm.z - m.vm.z) * 0.5; }
  }
  if (m.pt === undefined || ctx.t > m.pt) { m.pr = r; m.pt = ctx.t; }
  return r;
}

function reward(ctx) {
  const s = ctx.state, m = ctx.memory, dt = ctx.dt;
  const r = seeker(ctx);
  const d = Math.sqrt(r.x * r.x + r.y * r.y + r.z * r.z);
  const out = { energy: -0.1 * dt * (ctx.out["Motor FL"] + ctx.out["Motor FR"] + ctx.out["Motor RL"] + ctx.out["Motor RR"]) / 4 };
  if (m.hit) return out;
  m.minD = Math.min(m.minD, d);
  const my = s.y + r.y;   // missile height
  const ox = s.x + r.x - m.pad.x, oz = s.z + r.z - m.pad.z, oy = my - m.pad.y;
  const fromPad = Math.sqrt(ox * ox + oy * oy + oz * oz);
  if (d < KILL && fromPad > SAFE) {
    m.hit = true; m.tHit = ctx.t;
    m.standoff = fromPad;
    out.intercept = 10;
    out.standoff = Math.min(m.standoff / 10, 30);
    out.early = 5 * (ctx.info.duration - ctx.t) / ctx.info.duration;
    return out;
  }
  if (!m.leaked && ctx.t > 1 && my < m.pad.y + 1) { m.leaked = true; out.leak = -10; }
  out.closing = m.leaked ? 0 : -Math.min(d, 400) / 100 * dt;
  return out;
}

function failed(ctx) {
  const i = ctx.in;
  return !ctx.memory.hit && (ctx.state.crashed || Math.abs(i["att.roll"]) > 120 || i.alt > 300);
}
// End on failure, or 2.5 s after a hit (time for the replay to show the intercept), or once the missile has landed.
function terminate(ctx) {
  const m = ctx.memory;
  return failed(ctx) || (m.hit && ctx.t > m.tHit + 2.5) || (m.leaked && ctx.t > 12);
}

function fitness(ctx) {
  const m = ctx.memory, s = ctx.sum;
  // crashing early must never pay: charge the worst closing rate for the rest of the episode plus the leak
  const crash = failed(ctx) ? -5 - 4 * Math.max(0, ctx.info.duration - ctx.t) - (m.leaked ? 0 : 10) : 0;
  const miss = m.hit ? 0 : -Math.min(m.minD === undefined ? 400 : m.minD, 100) / 5;
  return { fitness: s.intercept + s.standoff + s.early + s.closing + s.leak + s.energy + crash + miss,
           terms: { crash: crash, miss: miss } };
}

function descriptor(ctx) { return [ctx.memory.tHit || ctx.info.duration, ctx.memory.standoff || 0]; }

// --- Genes (12). Starting values: timid pure pursuit (no lead, no gravity compensation, 30 deg lean): it chases
//     the missile's tail and misses.
function genome(base) {
  const g = (name, lo, hi, init) => base.genes.push({ name: name, group: "script", min: lo, max: hi, initial: init, sigma: (hi - lo) / 10 });
  g("hover", 0.05, 0.25, 0.1);
  g("kAlt", 0, 0.1, 0.02);
  g("kVs", 0, 0.1, 0.03);
  g("kAtt", 0, 0.01, 0.003);
  g("kRate", 0, 0.003, 0.0006);
  g("kPos", 0, 5, 0.5);
  g("kVel", 0, 10, 2);
  g("kYaw", 0, 0.006, 0.002);
  g("tiltMax", 10, 80, 30);        // lean limit, deg
  g("lead", 0, 2, 0);              // fraction of (missile velocity x time-to-go) to lead by
  g("gComp", 0, 2, 0);             // fraction of the gravity drop over time-to-go to aim under
  g("vClose", 5, 120, 20);         // assumed closing speed for time-to-go (m/s)
  return base;
}

function control(ctx) {
  const G = ctx.genome, m = ctx.memory;
  const r = seeker(ctx);
  const d = Math.sqrt(r.x * r.x + r.y * r.y + r.z * r.z);
  const tgo = Math.min(d / G.get("vClose"), 10);
  const vm = m.vm || { x: 0, y: 0, z: 0 };
  const L = G.get("lead") * tgo, drop = 0.5 * 9.81 * tgo * tgo * G.get("gComp");
  const aim = { dx: r.x + vm.x * L, dy: r.y + vm.y * L - drop, dz: r.z + vm.z * L };
  quad(ctx, {
    hover: G.get("hover"), kAlt: G.get("kAlt"), kVs: G.get("kVs"), kAtt: G.get("kAtt"), kRate: G.get("kRate"),
    kPos: G.get("kPos"), kVel: G.get("kVel"), kYaw: G.get("kYaw"), tiltMax: G.get("tiltMax"),
  }, aim, 0);
}

// --- Quad flight controller (shared by drone-hover / drone-race). Cascade: position -> lean angle -> attitude PD
//     -> motor mixer, plus altitude PD and yaw-rate damping, all in thrust-fraction units (0..1 of static thrust).
//     tgt = offset to the goal (m, world axes); yawSp = yaw-rate setpoint (deg/s).
function quad(ctx, G, tgt, yawSp) {
  const i = ctx.in, m = ctx.memory, dt = ctx.dt;
  const dx = tgt.dx, dy = tgt.dy, dz = tgt.dz;
  // ground velocity from the rate of change of the target offset (there is no velocity sensor), lightly filtered
  const vx = m.pdx === undefined ? 0 : -(dx - m.pdx) / dt, vz = m.pdz === undefined ? 0 : -(dz - m.pdz) / dt;
  m.vx = m.vx === undefined ? 0 : m.vx + (vx - m.vx) * 0.3; m.vz = m.vz === undefined ? 0 : m.vz + (vz - m.vz) * 0.3;
  m.pdx = dx; m.pdz = dz;
  const lim = G.tiltMax;
  const pitchSp = clamp(-(G.kPos * dx - G.kVel * m.vx), -lim, lim);   // nose down to go +x
  const rollSp = clamp(G.kPos * dz - G.kVel * m.vz, -lim, lim);       // roll positive to go +z
  const tilt = Math.min(Math.sqrt(i["att.pitch"] * i["att.pitch"] + i["att.roll"] * i["att.roll"]), 80) * Math.PI / 180;
  const f = (G.hover + G.kAlt * clamp(dy, -10, 10) - G.kVs * i.vs) / Math.max(Math.cos(tilt), 0.3);   // tilt compensation
  const p = G.kAtt * (pitchSp - i["att.pitch"]) - G.kRate * i["rate.pitch"];
  const r = G.kAtt * (rollSp - i["att.roll"]) - G.kRate * i["rate.roll"];
  const y = -G.kYaw * (i["rate.yaw"] - (yawSp || 0));   // speeding up the CW pair (FL, RR) yaws the body to negative rate
  const e = (v) => Math.pow(clamp(v, 0, 1), 1.5);   // thrust fraction -> motor command (static thrust ~ power^2/3)
  ctx.out["Motor FL"] = e(f + p + r + y);
  ctx.out["Motor FR"] = e(f + p - r - y);
  ctx.out["Motor RL"] = e(f - p + r - y);
  ctx.out["Motor RR"] = e(f - p - r + y);
}
